import {readWords} from './vocab.js';
// Matches wordaso's existing version-1 export. Never executes source code.
export function parseCatalogue(data){if(data?.version!==1||!data.books||Array.isArray(data.books)||typeof data.books!=='object')throw Error('wordasoの単語帳JSON（version: 1）を選んでください。');const books=[];for(const [key,book] of Object.entries(data.books)){if(!book||typeof book.label!=='string'||!Array.isArray(book.words))throw Error('単語帳の形式が正しくありません。');if(book.label.length>100||book.words.length>20000)throw Error('単語帳のサイズが大きすぎます。');const ids=new Set(),words=[];for(const item of book.words){if(!Number.isSafeInteger(item?.id)||item.id<1||ids.has(item.id)||typeof item.word!=='string'||typeof item.meaning!=='string')throw Error(book.label+'：番号・単語・訳の形式を確認してください。');ids.add(item.id);words.push({id:item.id,word:item.word,meaning:item.meaning});}if(words.length){words.sort((a,b)=>a.id-b.id);books.push({key,label:book.label,words});}}if(!books.length)throw Error('単語が入っていません。');return books;}
export function selectBookRange(book,from,to){if(!Number.isSafeInteger(from)||!Number.isSafeInteger(to)||from<1||to<from)throw Error('開始番号と終了番号を確認してください。');const entries=book.words.filter(w=>w.id>=from&&w.id<=to);if(entries.length<4)throw Error('選んだ範囲に4語以上必要です。');if(entries.some(w=>/[\r\n\t]/.test(w.word+w.meaning)))throw Error('改行・タブを含む項目があります。元データは変更せず、別の範囲を選んでください。');const raw=entries.map(w=>w.word+'\t'+w.meaning).join('\n'),parsed=readWords(raw);if(parsed.errors.length)throw Error('この範囲はゲームへ取り込めません：'+parsed.errors[0]);return {raw,count:parsed.entries.length,sourceCount:entries.length,label:book.label,from,to};}
